func HasEditorWith(preds ...predicate.User) predicate.DocumentNote {
	return predicate.DocumentNote(func(s *sql.Selector) {
		step := newEditorStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasReplacement applies the HasEdge predicate on the "replacement" edge.
func HasReplacement() predicate.DocumentNote {
	return predicate.DocumentNote(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, true, ReplacementTable, ReplacementColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

