// And groups predicates with the AND operator between them.
func And(predicates ...predicate.DocumentNote) predicate.DocumentNote {
	return predicate.DocumentNote(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.DocumentNote) predicate.DocumentNote {
	return predicate.DocumentNote(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.DocumentNote) predicate.DocumentNote {
	return predicate.DocumentNote(sql.NotPredicates(p))
}
